// GENERATED by scripts/make-platform-workflows.js from src/. Edit the source, not this node.
const TC = {};
// TerraCorridor segment core. One record per kilometre is the platform: every module pins its facts to
// a position along the line (chainage, in metres from the start) and reads them back per segment.
// Pure functions, no imports, [lon, lat] order like src/engine.js.
(function (root) {
  const toRad = (d) => (d * Math.PI) / 180;

  // Builds a lookup from the ordered segments: a flat list of line pieces with their chainage,
  // and the chainage range each segment covers. Uses a local flat projection, good to well under
  // a metre over a corridor of this size.
  function buildIndex(segments) {
    const segs = (segments || []).filter((s) => Array.isArray(s.centreline) && s.centreline.length >= 2);
    if (!segs.length) throw new Error('no segments with a centreline');
    const lats = segs.flatMap((s) => s.centreline.map((p) => p[1]));
    const lat0 = lats.reduce((a, b) => a + b, 0) / lats.length;
    const kx = 111320 * Math.cos(toRad(lat0)), ky = 110574;
    const pieces = [], ranges = [];
    let acc = 0;
    for (const s of segs) {
      const fromM = acc;
      for (let i = 1; i < s.centreline.length; i++) {
        const a = s.centreline[i - 1], b = s.centreline[i];
        const ax = a[0] * kx, ay = a[1] * ky, bx = b[0] * kx, by = b[1] * ky;
        const len = Math.hypot(bx - ax, by - ay);
        if (len === 0) continue;
        pieces.push({ ax, ay, bx, by, len, fromM: acc });
        acc += len;
      }
      ranges.push({ id: s.id, kmFrom: s.kmFrom, kmTo: s.kmTo, fromM, toM: acc });
    }
    return { kx, ky, pieces, ranges, lengthM: acc };
  }

  // Nearest point on the line: how far off the centreline, and how far along it.
  function locate(index, lonLat) {
    const x = lonLat[0] * index.kx, y = lonLat[1] * index.ky;
    let best = Infinity, chainageM = 0;
    for (const p of index.pieces) {
      const dx = p.bx - p.ax, dy = p.by - p.ay;
      const t = Math.max(0, Math.min(1, ((x - p.ax) * dx + (y - p.ay) * dy) / (p.len * p.len)));
      const d = Math.hypot(x - (p.ax + t * dx), y - (p.ay + t * dy));
      if (d < best) { best = d; chainageM = p.fromM + t * p.len; }
    }
    return { offsetM: best, chainageM };
  }

  function segmentAt(index, chainageM) {
    const r = index.ranges.find((q) => chainageM >= q.fromM && chainageM < q.toM) || (chainageM >= index.lengthM ? index.ranges[index.ranges.length - 1] : null);
    return r ? r.id : null;
  }

  // Segments that a stretch of line touches. A point obligation (fromM === toM) touches one segment.
  function overlapping(index, fromM, toM) {
    const lo = Math.min(fromM, toM), hi = Math.max(fromM, toM);
    if (lo === hi) { const id = segmentAt(index, lo); return id ? [id] : []; }
    return index.ranges.filter((r) => r.fromM < hi && r.toM > lo).map((r) => r.id);
  }

  const rangeOf = (index, id) => index.ranges.find((r) => r.id === id) || null;

  // Dates as ISO strings (YYYY-MM-DD). Month arithmetic is all the modules need.
  function addMonths(iso, n) {
    const d = new Date(iso + 'T00:00:00Z');
    const day = d.getUTCDate();
    d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() + n);
    const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
    d.setUTCDate(Math.min(day, last));
    return d.toISOString().slice(0, 10);
  }
  const addHours = (isoDateTime, h) => new Date(new Date(isoDateTime).getTime() + h * 3600000).toISOString();
  const monthsBetween = (a, b) => Math.round(((new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / 86400000 / 30.4375) * 10) / 10;
  const day = (x) => (x instanceof Date ? x.toISOString() : String(x)).slice(0, 10);

  const api = { buildIndex, locate, segmentAt, overlapping, rangeOf, addMonths, addHours, monthsBetween, day };
  root.TC_SEGMENTS = api;
})(TC);
// TerraCorridor field feedback (W7). Built first because every module depends on it.
// A crew that walks a kilometre for one reason sees things that matter to the others. Each finding
// is written back to the segment record, and each one is paired with what the system had said
// beforehand. Those pairs are the dataset nobody else has.
(function (root) {
  const KINDS = {
    dwelling_count:      { module: 'class_location',   needsValue: true,  label: 'Dwellings counted in the assessment window' },
    new_structure:       { module: 'class_location',   needsValue: false, label: 'New building or foundation seen' },
    ground_movement:     { module: 'geohazard',        needsValue: false, label: 'Ground movement, erosion or exposed pipe' },
    no_hazard_found:     { module: 'geohazard',        needsValue: false, label: 'Walked and found nothing' },
    obligation_met:      { module: 'land_obligations', needsValue: false, label: 'Obligation carried out' },
    obligation_missed:   { module: 'land_obligations', needsValue: false, label: 'Obligation missed or disputed' },
    unauthorized_work:   { module: 'encroachment',     needsValue: false, label: 'Digging or a structure inside the prescribed area' },
  };
  // A finding for one module also informs these.
  const ALSO = { new_structure: ['encroachment'], unauthorized_work: ['class_location'], ground_movement: ['land_obligations'] };

  function normalize(raw) {
    const k = KINDS[raw.kind], problems = [];
    if (!k) problems.push('unknown kind of finding');
    if (!raw.segment) problems.push('no segment');
    if (!raw.by) problems.push('no name');
    if (k && k.needsValue && (raw.value == null || raw.value === '' || Number.isNaN(+raw.value) || +raw.value < 0)) problems.push('needs a number');
    const at = raw.at || new Date().toISOString();
    return { finding: { id: raw.id || `F-${raw.segment}-${at.replace(/\D/g, '').slice(0, 14)}`, segment: raw.segment, kind: raw.kind, module: k ? k.module : null, also: ALSO[raw.kind] || [],
      value: raw.value == null || raw.value === '' ? null : +raw.value, note: raw.note || null, withinPrescribedArea: raw.withinPrescribedArea === true, workOrder: raw.workOrder || null, by: raw.by || null, at }, problems };
  }

  // What the system believed about this kilometre before the crew went, in the same terms as the finding.
  function predictionFor(record, kind) {
    const c = record.classLocation, g = record.geohazard;
    if (kind === 'dwelling_count') return c ? { value: c.units.existing, text: `${c.units.existing} dwellings estimated` } : null;
    if (kind === 'new_structure') return c ? { value: c.units.committed + c.units.possible > 0, text: `${c.units.committed + c.units.possible} units permitted but not yet counted` } : null;
    if (kind === 'ground_movement' || kind === 'no_hazard_found') return g ? { value: ['amber', 'red', 'red-uncertain'].includes(g.tier), text: `${g.tier} for ${g.hazard || 'ground failure'}` } : null;
    if (kind === 'unauthorized_work') return { value: (record.encroachment || []).length > 0, text: `${(record.encroachment || []).length} flags on file` };
    return null;
  }

  // Writes findings into a copy of the record. A counted number replaces an estimate and says so.
  function apply(record, findings, classCfg) {
    const r = JSON.parse(JSON.stringify(record));
    r.field = r.field || [];
    const mine = (findings || []).filter((f) => f.segment === r.id).sort((a, b) => a.at.localeCompare(b.at));
    for (const f of mine) {
      r.field.push({ id: f.id, kind: f.kind, module: f.module, also: f.also, value: f.value, note: f.note, by: f.by, at: f.at });
      if (f.kind === 'dwelling_count' && r.classLocation) {
        const c = r.classLocation, t = (classCfg && classCfg.thresholds) || { class2: 11, class3: 46 };
        const cls = (u) => (u >= t.class3 ? 3 : u >= t.class2 ? 2 : 1);
        c.units.estimatedBeforeCount = c.units.existing; c.units.existing = f.value;
        c.class.now = cls(f.value); c.class.committed = cls(f.value + c.units.committed); c.class.possible = cls(f.value + c.units.committed + c.units.possible);
        c.class.isLowerBound = false;
        c.basis = `counted on site by ${f.by} on ${f.at.slice(0, 10)}`;
        c.fieldCounted = true;
      }
      if (f.kind === 'new_structure' && f.withinPrescribedArea) (r.encroachment = r.encroachment || []).push({ id: f.id, kind: 'structure', source: 'field finding', observedAt: f.at, note: f.note });
      if (f.kind === 'unauthorized_work') (r.encroachment = r.encroachment || []).push({ id: f.id, kind: 'ground_disturbance', source: 'field finding', observedAt: f.at, note: f.note });
      if ((f.kind === 'ground_movement' || f.kind === 'no_hazard_found') && r.geohazard) (r.geohazard.fieldEvidence = r.geohazard.fieldEvidence || []).push({ id: f.id, confirmed: f.kind === 'ground_movement', note: f.note, by: f.by, at: f.at });
    }
    return r;
  }

  // One row per finding: what was predicted, what was seen. This table only exists because someone used the tool.
  function outcomeLabels(recordsBefore, findings) {
    const byId = Object.fromEntries((recordsBefore || []).map((r) => [r.id, r]));
    return (findings || []).map((f) => {
      const rec = byId[f.segment], p = rec ? predictionFor(rec, f.kind) : null;
      let agreed = null, error = null;
      if (p && f.kind === 'dwelling_count') { error = f.value - p.value; agreed = Math.abs(error) <= Math.max(2, 0.1 * f.value); }
      else if (p && f.kind === 'ground_movement') agreed = p.value === true;
      else if (p && f.kind === 'no_hazard_found') agreed = p.value === false;
      else if (p && (f.kind === 'new_structure' || f.kind === 'unauthorized_work')) agreed = p.value === true;
      return { finding: f.id, segment: f.segment, module: f.module, kind: f.kind, predicted: p ? p.text : null, observed: f.value != null ? f.value : (KINDS[f.kind] || {}).label, agreed, error, at: f.at, by: f.by };
    });
  }

  // Plain counts per module. No probabilities: there are too few rows to claim one.
  function scoreboard(labels) {
    const out = {};
    for (const l of labels || []) {
      const m = out[l.module] || (out[l.module] = { findings: 0, comparable: 0, agreed: 0 });
      m.findings++; if (l.agreed != null) { m.comparable++; if (l.agreed) m.agreed++; }
    }
    return out;
  }

  const api = { KINDS, ALSO, normalize, predictionFor, apply, outcomeLabels, scoreboard };
  root.TC_FEEDBACK = api;
})(TC);

const body = $input.first().json.body || {};
const { finding, problems } = TC.TC_FEEDBACK.normalize(body);
return [{ json: problems.length ? { ok: false, error: 'Finding refused: ' + problems.join(', ') + '.', allowed: Object.keys(TC.TC_FEEDBACK.KINDS) } : { ok: true, finding } }];

// GENERATED by scripts/make-platform-workflows.js from src/. Edit the source, not this node.
const TC = {};
// TerraCorridor ledger: the one approval gate every module goes through, and the evidence pack.
// A module only ever drafts. A named person approves, rejects or overrides. Each decision is
// chained to the one before it with SHA-256, so a record that was edited afterwards shows.
// This is the part a competitor cannot scrape: what changed, what the operator chose, what it
// cost, what the crew found, one history per kilometre.
(function (root) {
  // Synchronous SHA-256 in plain JS so the same code runs in Node, a browser and an n8n Code node.
  const K = [];
  (function () { let n = 2, i = 0; const frac = (x) => ((x - Math.floor(x)) * 4294967296) | 0; while (i < 64) { let p = true; for (let d = 2; d * d <= n; d++) if (n % d === 0) { p = false; break; } if (p) K[i++] = frac(Math.cbrt(n)); n++; } })();
  function utf8(s) { const o = []; for (const ch of String(s)) { let c = ch.codePointAt(0); if (c < 0x80) o.push(c); else if (c < 0x800) o.push(0xc0 | (c >> 6), 0x80 | (c & 63)); else if (c < 0x10000) o.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); else o.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); } return o; }
  function sha256(text) {
    const b = utf8(text), bits = b.length * 8;
    b.push(0x80); while (b.length % 64 !== 56) b.push(0);
    const hi = Math.floor(bits / 4294967296), lo = bits >>> 0;
    b.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255, (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
    const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    const w = new Array(64), r = (x, n) => (x >>> n) | (x << (32 - n));
    for (let o = 0; o < b.length; o += 64) {
      for (let i = 0; i < 16; i++) w[i] = (b[o + i * 4] << 24) | (b[o + i * 4 + 1] << 16) | (b[o + i * 4 + 2] << 8) | b[o + i * 4 + 3];
      for (let i = 16; i < 64; i++) { const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10); w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0; }
      let [a, bb, c, d, e, f, g, h] = H;
      for (let i = 0; i < 64; i++) {
        const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
        const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0;
      }
      H[0] = (H[0] + a) | 0; H[1] = (H[1] + bb) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
    }
    return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
  }

  // Same object, same text, whatever order its keys were written in.
  function canonical(v) {
    if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
    if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
    return '{' + Object.keys(v).sort().filter((k) => v[k] !== undefined).map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
  }
  const hashOf = (v) => sha256(typeof v === 'string' ? v : canonical(v));

  const MODULES = ['class_location', 'geohazard', 'land_obligations', 'encroachment'];
  const GENESIS = '0'.repeat(64);

  // A module proposes something. It is a draft until a person decides.
  function draft(module, segmentId, kind, payload, opts = {}) {
    if (!MODULES.includes(module)) throw new Error('unknown module: ' + module);
    if (!segmentId) throw new Error('a draft needs a segment');
    const at = opts.at || new Date().toISOString();
    const inputsHash = hashOf(payload);
    return { id: `${module}:${segmentId}:${kind}:${inputsHash.slice(0, 10)}`, module, segment: segmentId, kind, payload, inputsHash, status: 'draft', draftedAt: at, draftedBy: opts.by || 'system' };
  }

  // Appends one entry and returns the new ledger. Rejecting or overriding needs a reason; nobody approves anonymously.
  function append(ledger, entry) {
    const prev = ledger.length ? ledger[ledger.length - 1].hash : GENESIS;
    const body = { ...entry, seq: ledger.length + 1, prev };
    return [...ledger, { ...body, hash: hashOf(body) }];
  }
  function decide(ledger, action, d) {
    const decision = d && d.decision;
    if (!['approve', 'reject', 'override'].includes(decision)) throw new Error('decision must be approve, reject or override');
    if (!d.by || !String(d.by).trim()) throw new Error('a decision needs the name of the person making it');
    if (decision !== 'approve' && !(d.reason && String(d.reason).trim())) throw new Error(decision + ' needs a reason');
    if (ledger.some((e) => e.type === 'decision' && e.action === action.id)) throw new Error('already decided: ' + action.id);
    return append(ledger, { type: 'decision', action: action.id, module: action.module, segment: action.segment, kind: action.kind, inputsHash: action.inputsHash,
      decision, by: String(d.by).trim(), reason: d.reason || null, chosen: d.chosen || null, estimate: d.estimate == null ? null : d.estimate, at: d.at || new Date().toISOString() });
  }
  // What happened afterwards: a crew finding, or what the work really cost. Same chain.
  function recordOutcome(ledger, o) {
    if (!o || !o.segment) throw new Error('an outcome needs a segment');
    if (!o.by) throw new Error('an outcome needs the name of the person reporting it');
    return append(ledger, { type: o.type === 'actual_cost' ? 'actual_cost' : 'finding', action: o.action || null, module: o.module || null, segment: o.segment, finding: o.finding || null, value: o.value == null ? null : o.value, note: o.note || null, by: o.by, at: o.at || new Date().toISOString() });
  }

  function verify(ledger) {
    let prev = GENESIS;
    for (let i = 0; i < ledger.length; i++) {
      const { hash, ...body } = ledger[i];
      if (body.prev !== prev || body.seq !== i + 1 || hashOf(body) !== hash) return { ok: false, brokenAt: i + 1 };
      prev = hash;
    }
    return { ok: true, entries: ledger.length, head: prev };
  }

  const statusOf = (ledger, action) => { const e = ledger.find((x) => x.type === 'decision' && x.action === action.id); return e ? (e.decision === 'approve' ? 'approved' : e.decision === 'reject' ? 'rejected' : 'overridden') : 'draft'; };

  // One kilometre's history, oldest first: the decision record.
  function decisionRecord(ledger, segmentId) {
    return ledger.filter((e) => e.segment === segmentId).map((e) => ({ seq: e.seq, at: e.at, type: e.type, module: e.module, what: e.type === 'decision' ? `${e.decision} ${e.kind}${e.chosen ? ': ' + e.chosen : ''}` : e.type === 'actual_cost' ? 'actual cost reported' : (e.finding || 'finding'),
      by: e.by, reason: e.reason || e.note || null, estimate: e.estimate == null ? null : e.estimate, value: e.value == null ? null : e.value, hash: e.hash }));
  }

  // Everything an auditor needs for one kilometre: the inputs with their hashes, every decision, and whether the chain is intact.
  function evidencePack(record, ledger, sources = [], opts = {}) {
    const check = verify(ledger);
    return {
      segment: record.id, km: [record.kmFrom, record.kmTo], generatedAt: opts.at || new Date().toISOString(),
      recordHash: hashOf(record),
      sources: sources.map((s) => ({ name: s.name, dataset: s.dataset || null, url: s.url || null, fetchedAt: s.fetchedAt || null, sha256: s.sha256 || (s.content != null ? hashOf(s.content) : null) })),
      decisions: decisionRecord(ledger, record.id),
      chain: { ok: check.ok, entries: ledger.length, head: check.head || null, brokenAt: check.brokenAt || null },
    };
  }

  const api = { sha256, canonical, hashOf, MODULES, GENESIS, draft, append, decide, recordOutcome, verify, statusOf, decisionRecord, evidencePack };
  root.TC_LEDGER = api;
})(TC);

const rows = (name) => { try { return $(name).all().map((i) => i.json).filter((j) => j && !j.error && Object.keys(j).length); } catch (e) { return []; } };
const ledgerOf = (name) => rows(name).map((r) => { try { return JSON.parse(r.entry_json); } catch (e) { return null; } }).filter(Boolean).sort((a, b) => a.seq - b.seq);
const f = $('Validate finding').first().json.finding;
const ledger = ledgerOf('Get ledger');
const check = TC.TC_LEDGER.verify(ledger);
if (!check.ok) throw new Error('Ledger chain is broken at entry ' + check.brokenAt + '. Nothing was written.');
const next = TC.TC_LEDGER.recordOutcome(ledger, { segment: f.segment, module: f.module, finding: f.kind, value: f.value, note: f.note, by: f.by, at: f.at, action: f.workOrder });
const e = next[next.length - 1];
return [{ json: { ok: true, finding_id: f.id, segment_id: f.segment, kind: f.kind, module: f.module, also_json: JSON.stringify(f.also), value: f.value == null ? '' : String(f.value), note: f.note || '', within_prescribed_area: String(f.withinPrescribedArea), work_order_id: f.workOrder || '', reported_by: f.by, reported_at: f.at,
  seq: String(e.seq), hash: e.hash, prev: e.prev, type: e.type, entry_json: JSON.stringify(e) } }];
